#!/usr/bin/env node
/*
 * Maintenance script — regenerates .github/suite-durations.json from historical
 * CI JUnit artifacts, so build-matrix.js can size shards by measured RUNTIME
 * (duration-aware sharding) instead of scenario count alone.
 *
 * It scans test-results/ci-artifacts/<runId>/<suite_id>-results/cucumber-junit.xml,
 * sums the per-<testcase> `time` (seconds) for each run to get that suite's total
 * scenario CPU-seconds, maps shard artifacts (<base>-<n>-results) back to their
 * base suite_id, and records the MEDIAN across runs (robust to one slow/flaky run).
 *
 * The `time` attribute is the final-attempt duration, so it slightly UNDER-counts
 * wall time (retry attempts aren't included) — build-matrix.js compensates with a
 * generous per-shard time target (headroom vs the step timeout).
 *
 * Run this occasionally as fresh ci-artifacts land, then commit the JSON.
 * Usage: node .github/scripts/collect-durations.js
 */

const fs = require('fs');
const path = require('path');

const ARTIFACTS = 'test-results/ci-artifacts';
const MANIFEST = '.github/suites.json';
const OUT = '.github/suite-durations.json';

function baseSuiteIds() {
  const m = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  return [...(m['non-booking'] || []), ...(m.booking || [])].map((s) => s.suite_id);
}

// Map an artifact dir name (e.g. "flights-general-non-booking-2-results") to a
// known base suite_id ("flights-general-non-booking"), or null if unknown.
function toBaseId(dirName, ids) {
  let id = dirName.replace(/-results$/, '');
  if (ids.includes(id)) return id;
  const noShard = id.replace(/-\d+$/, ''); // strip trailing -<n> shard suffix
  return ids.includes(noShard) ? noShard : null;
}

function sumTestcaseSeconds(xmlFile) {
  let xml;
  try { xml = fs.readFileSync(xmlFile, 'utf8'); } catch { return null; }
  let total = 0, n = 0;
  const re = /<testcase\b[^>]*\btime="([\d.]+)"/g;
  let m;
  while ((m = re.exec(xml)) !== null) { total += parseFloat(m[1]) || 0; n++; }
  return n === 0 ? null : { seconds: total, scenarios: n };
}

function median(nums) {
  const a = [...nums].sort((x, y) => x - y);
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}

function main() {
  if (!fs.existsSync(ARTIFACTS)) {
    process.stderr.write(`collect-durations: no ${ARTIFACTS} directory\n`);
    process.exit(1);
  }
  const ids = baseSuiteIds();
  const perSuite = {}; // base id -> { seconds:[], scenarios:[] }

  for (const run of fs.readdirSync(ARTIFACTS, { withFileTypes: true })) {
    if (!run.isDirectory()) continue;
    const runDir = path.join(ARTIFACTS, run.name);
    // Aggregate shard artifacts within a run back to their base suite first.
    const runTotals = {}; // base id -> { seconds, scenarios }
    for (const entry of fs.readdirSync(runDir, { withFileTypes: true })) {
      if (!entry.isDirectory() || !entry.name.endsWith('-results')) continue;
      const base = toBaseId(entry.name, ids);
      if (!base) continue;
      const r = sumTestcaseSeconds(path.join(runDir, entry.name, 'cucumber-junit.xml'));
      if (!r) continue;
      const acc = (runTotals[base] = runTotals[base] || { seconds: 0, scenarios: 0 });
      acc.seconds += r.seconds;
      acc.scenarios += r.scenarios;
    }
    for (const [base, r] of Object.entries(runTotals)) {
      const s = (perSuite[base] = perSuite[base] || { seconds: [], scenarios: [] });
      s.seconds.push(r.seconds);
      s.scenarios.push(r.scenarios);
    }
  }

  const out = { _comment: `Generated by collect-durations.js from ${ARTIFACTS}. Per suite: median total scenario CPU-seconds across runs (final-attempt times; retries not included). build-matrix.js divides by group parallelism to estimate wall time and size shards. Regenerate + commit as new artifacts land.` };
  const suites = {};
  for (const [id, s] of Object.entries(perSuite).sort()) {
    suites[id] = {
      cpu_seconds: Math.round(median(s.seconds)),
      scenarios: Math.round(median(s.scenarios)),
      runs: s.seconds.length,
    };
  }
  out.suites = suites;
  fs.writeFileSync(OUT, JSON.stringify(out, null, 2) + '\n');

  // Console calibration table
  process.stdout.write(`\nSuite durations (median across runs) -> ${OUT}\n`);
  process.stdout.write('suite_id                                cpu_min  scn  runs\n');
  for (const [id, v] of Object.entries(suites)) {
    process.stdout.write(`${id.padEnd(38)} ${String((v.cpu_seconds / 60).toFixed(1)).padStart(6)}  ${String(v.scenarios).padStart(3)}  ${v.runs}\n`);
  }
}

main();
